#!/bin/bash
set +e
rm -f /tmp/uwv9.b64 /tmp/uwv9.py
printf '%s' '' >> /tmp/uwv9.b64
printf '%s' '' >> /tmp/uwv9.b64
printf '%s' '' >> /tmp/uwv9.b64
printf '%s' '' >> /tmp/uwv9.b64
printf '%s' '' >> /tmp/uwv9.b64
printf '%s' '' >> /tmp/uwv9.b64
printf '%s' 'rKwgMi8nIGluIHQzKQogICAgcHJpbnQoJ1BBR0VfMV9CQUNLJywgZ2V0KCcvcGx1Z2luL0VtYnlVbndhdGNoZWRXYXNoL3NlbGVjdF9wYWdlJywgcGFnZT0xKSkKZWxzZToKICAgIHByaW50KCdOT19ST1dTX1RPX1RFU1QnKQo=' >> /tmp/uwv9.b64
base64 -d /tmp/uwv9.b64 > /tmp/uwv9.py
echo '=== restart container ==='
docker restart moviepilot-v3
for i in $(seq 1 80); do
  if docker logs --tail 400 %s 2>&1 | grep -q 'EmbyUnwatchedWash'; then echo wait_ok=$i; break; fi
  sleep 3
done
docker exec -u 1000:10 moviepilot-v3 sh -c 'grep -n plugin_version /app/app/plugins/embyunwatchedwash/__init__.py | head -2'
docker logs --tail 400 moviepilot-v3 2>&1 | grep -E 'EmbyUnwatchedWash' | tail -4
echo '=== verifier ==='
docker exec -i -u 1000:10 moviepilot-v3 python - < /tmp/uwv9.py 2>&1 | tail -70
echo '=== sql state ==='
docker exec postgres_moviepilot psql -U imushroom -d moviepilot -t -A -c "select config_data from plugininstance where source_plugin_id ilike '%UnwatchedWash%';"
docker exec postgres_moviepilot psql -U imushroom -d moviepilot -t -A -c "select plugin_id, key, value from plugindata where plugin_id ilike '%UnwatchedWash%' and key = 'list_page';"
echo '---end---'
